?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Site settings</title><link rel="stylesheet" href="<?=e(url('assets/css/admin.css'))?>"></head><body><div class="shell"><?php require __DIR__.'/_nav.php';?><main><div class="top"><div><small>CUSTOMIZE YOUR WEBSITE</small><h1>Site settings</h1></div><a href="<?=e(url('index.php'))?>" target="_blank">Preview site ↗</a></div><?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><form class="panel" method="post"><?=csrf_field()?><p>Edit global content used throughout the public website.</p><?php foreach($fields as $k=>$label):?><label><?=e($label)?><?php if(in_array($k,['hero_text','about_text','footer_text','meta_description'])):?><textarea name="<?=e($k)?>" rows="3"><?=e(setting($k))?></textarea><?php else:?><input name="<?=e($k)?>" value="<?=e(setting($k))?>"><?php endif;?></label><?php endforeach;?><h3>Upload media</h3><p>Upload an image then copy its URL into the hero image field or a content item's image field.</p><div class="upload"><input type="file" id="media" accept="image/jpeg,image/png,image/webp,image/gif"><button type="button" id="upload" class="secondary">Upload image</button><span id="result"></span></div><button class="primary">Save settings</button></form></main></div><script>document.getElementById('upload').onclick=async()=>{let f=document.getElementById('media').files[0],r=document.getElementById('result');if(!f){r.textContent='Choose an image first';return;}let d=new FormData();d.append('image',f);d.append('_csrf',<?=json_encode(csrf_token())?>);r.textContent='Uploading…';try{let x=await fetch(<?=json_encode(url('admin/upload.php'))?>,{method:'POST',body:d}),j=await x.json();if(!x.ok)throw Error(j.error);await navigator.clipboard.writeText(j.url);r.textContent='Uploaded; URL copied: '+j.url;}catch(e){r.textContent=e.message;}};</script></body></html>